        except StopIteration:', 'retval.append(f"    {body_parameter.client_name} = {{{parameter_string}}}', 'retval.append(f'{ser_ctxt_name} = {{"xml": {{{xml_serialization_ctxt}}}}}', 'lambda x,y,z: x,")', 'raise ValueError("This method can't be called if the operation doesn't need parameter flattening")', 'raise ValueError("This method can't be called if the operation doesn't need parameter flattening")', 'raise TypeError('missing required argument: {p.client_name}')")', 'raise ClientAuthenticationError(response=response{}{})', 'raise ResourceNotFoundError(response=response{}{})', 'raise ResourceExistsError(response=response{}{})', 'raise ResourceNotModifiedError(response=response{}{})', 'raise HttpResponseError(response=response{}{})', '            if body_param.constant or body_param.method_location != ParameterMethodLocation.KWARG:
