    operation.responses = [
        Response(
            yaml_data={"statusCodes": [200]},
            code_model=code_model,
            headers=[],
            type=base_type,
        ),
        Response(
            yaml_data={"statusCodes": [202]},
            code_model=code_model,
            headers=[],
            type=base_type,
        ),
